import { BoxPlot, type BoxPlotSeries } from '@absoluteui/components/box-plot';

const series: BoxPlotSeries[] = [
  { id: 'prod', label: 'Production', data: [[120, 135, 150, 160, 180, 420], { min: 90, q1: 110, median: 125, q3: 140, max: 170, outliers: [310] }] },
  { id: 'staging', label: 'Staging', data: [[140, 150, 170, 190, 210], null] },
];

const host = document.createElement('div');
document.body.append(host);
BoxPlot.create(host, {
  label: 'Request latency by region',
  categories: ['Europe', 'North America'],
  series,
  valueAxis: { label: 'Milliseconds' },
  valueFormat: { maximumFractionDigits: 0 },
});

import { BoxPlot, boxStats, quantile } from '@absoluteui/components/box-plot';

const samples = [4.1, 3.8, 5.2, 4.7, 9.9, 4.4, 4.0];
const stats = boxStats(samples);
const p90 = quantile([...samples].sort((a, b) => a - b), 0.9);

const host = document.querySelector<HTMLElement>('#build-times');
if (host) {
  const chart = BoxPlot.create(host, {
    label: 'Build time',
    description: `90th percentile: ${p90.toFixed(1)} min`,
    categories: ['main'],
    series: [{ id: 'ci', label: 'CI', data: [stats] }],
  });
  chart.update({ whiskers: 'minmax', series: [{ id: 'ci', label: 'CI', data: [samples] }] });
}
